  if(a==='metal-delivery-create')return <><div className="metal-form-grid">{input('date','送货日期','date')}{input('dueDate','要求收回日期','date')}{input('reference','送货凭据编号')}{area('note','送货备注')}</div><div className="metal-form-divider"><h4>分批送货明细</h4>{button('增加送货明细',()=>addLine({jobId:'',jobLineId:'',quantity:''}))}</div>{draft.lines.map((l,i)=>{const j=data.jobs.find(j=>j.id===l.jobId),line=j?.lines.find(x=>x.id===l.jobLineId),used=data.deliveries.filter(x=>!x.voided&&x.status!=='cancelled').flatMap(x=>x.lines).filter(x=>x.jobLineId===line?.id&&!x.reworkQcId).reduce((n,x)=>n+x.quantity,0);return <div className="metal-form-line" key={i}>{lineSelect(i,'jobId','加工单',data.jobs.filter(j=>j.status==='confirmed').map(j=>({value:j.id,label:`${j.number} / ${j.supplierName}`})),jobId=>patchLine(i,{jobId,jobLineId:'',quantity:''}))}{lineSelect(i,'jobLineId','加工明细',(j?.lines||[]).map(x=>({value:x.id,label:demandLabel(x.demandId)})),jobLineId=>patchLine(i,{jobLineId,quantity:''}))}{lineInput(i,'quantity','本次准备数量')}{deleteLine(i)}{line&&<small>加工单数量 {num(line.quantity)} · 已准备/发出 {num(used)} · 未安排 {num(Math.max(0,line.quantity-used-released(line.id)))} · 已确认实物可用 {num(balance(line.demandId)?.stockAvailable||0)} {demand(line.demandId)?.unit}</small>}</div>;})}<div className="metal-hint">先生成送货草稿，核对实物后再执行“确认实际发出”。默认打印无价供应商签收版。</div></>;
