  if(a==='metal-issue-create'){const q=data.quality.find(q=>q.id===v.qcId),d=demand(q?.demandId||''),plans=new Set(d?.sources.map(s=>s.planId)||[]),used=data.issues.filter(i=>!i.voided&&i.qcId===q?.id).reduce((n,i)=>n+i.quantity,0);return <><div className="metal-form-grid">{select('qcId','合格质检批次',data.quality.filter(q=>!q.voided&&q.billableGood+q.freeGood>0).map(q=>({value:q.id,label:`${demandLabel(q.demandId)} / ${q.date} / 合格 ${num(q.billableGood+q.freeGood)}`})),qcId=>patch({qcId,planId:''}))}{select('planId','实际领用款式 / 计划',data.plans.filter(p=>plans.has(p.id)).map(p=>({value:p.id,label:`${p.orderNo} / ${p.style} / ${num(p.quantity)}付 / ${p.dueDate}`})))}{input('quantity','实际领用配件数量','number')}{dateFields}</div>{q&&<div className="metal-preview">本批合格 {num(q.billableGood+q.freeGood)} · 已领用 {num(used)} · 尚可领用 {num(Math.max(0,q.billableGood+q.freeGood-used))} {d?.unit}。</div>}</>;}
  if(a==='metal-settlement-create'){const occupied=new Set(data.settlements.filter(s=>!s.voided&&s.status!=='cancelled').flatMap(s=>s.qcIds)),rows=data.quality.filter(q=>!q.voided&&q.amountIncTax>0&&!occupied.has(q.id)),usedAdjustments=new Set(data.settlements.filter(s=>!s.voided&&s.status!=='cancelled').flatMap(s=>s.adjustmentIds||[]));return <><div className="metal-form-grid">{input('period','对账账期','month')}{input('reference','对账依据')}{area('note','差异说明与备注')}</div><div className="metal-hint">选择同供应商、同币种且属于本账期的计费质检。可先按日期或供应商筛选，选择完整匹配结果后编制单据。扣补须已经确认并且与本单来源对应。</div><MetalTable title="待对账计费明细" rows={rows} columns={[{label:'供应商',value:r=>r.quote.supplierName},...qcColumns]} selected={v.qcIds} onSelect={qcIds=>patch({qcIds})} pageSize={10}/><MetalTable title="可纳入对账的已确认扣补" rows={data.adjustments.filter(x=>!x.voided&&x.status==='approved'&&!usedAdjustments.has(x.id))} columns={[col('关联质检','qcId'),col('原因','reason'),col('依据','reference'),...(allowed?.price?[col('含税扣补金额','amountIncTax'),col('币种','currency')]:[]),...auditColumns]} selected={v.adjustmentIds||[]} onSelect={adjustmentIds=>patch({adjustmentIds})} pageSize={10}/></>;}
  if(a==='metal-payment-create'){const s=data.settlements.find(s=>s.id===v.settlementId),paid=data.payments.filter(p=>!p.voided&&p.settlementId===s?.id).reduce((n,p)=>n+p.amount,0);return <><div className="metal-form-grid">{select('settlementId','已确认对账单',data.settlements.filter(s=>!s.voided&&s.status==='confirmed').map(s=>({value:s.id,label:`${s.number} / ${s.supplierName} / ${s.period}`})))}{input('amount','本次实际付款金额','number')}{dateFields}</div>{s&&allowed?.price&&<div className="metal-preview">确认应付 {amount(s.amountIncTax)} · 已付 {amount(paid)} · 剩余 {amount(s.amountIncTax-paid)} {s.currency}。</div>}</>;}
  if(a==='metal-adjustment-create')return <><div className="metal-form-grid">{select('qcId','关联计费质检',data.quality.filter(q=>!q.voided).map(q=>({value:q.id,label:`${demandLabel(q.demandId)} / ${q.date} / ${q.quote.supplierName}`})))}{input('amountIncTax','含税扣补金额','number',true,'正数为补款，负数为扣款，不能填零。')}{input('reference','扣补依据')}{area('reason','扣补原因',true)}</div><div className="metal-hint">先保存草稿，再由有权限人员确认扣补；确认后的金额可纳入供应商对账。</div></>;
